import{_ as r,C as n,o as l,c as i,aj as e,E as t}from"./framework.js";const b=JSON.parse('{"title":"域名管理 | Cms / Manual | Documentation","description":"域名管理 in Kooboo: 每个 Kooboo 账号自带免费域名，适合网站未上线时先测试。正式上线通常要另购域名，再绑定到站点。","frontmatter":{"title":"域名管理 | Cms / Manual | Documentation","description":"域名管理 in Kooboo: 每个 Kooboo 账号自带免费域名，适合网站未上线时先测试。正式上线通常要另购域名，再绑定到站点。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/manual/domains.html"}]]},"headers":[],"relativePath":"zh/cms/manual/domains.md","filePath":"cms/manual/domains.md","lastUpdated":1793060327000}'),s={name:"zh/cms/manual/domains.md"};function d(c,o,m,h,_,u){const a=n("DocImage");return l(),i("div",null,[o[0]||(o[0]=e('<h1 id="域名管理" tabindex="-1">域名管理 <a class="header-anchor" href="#域名管理" aria-label="Permalink to &quot;域名管理&quot;">​</a></h1><p>每个 Kooboo 账号自带免费域名，适合网站未上线时先测试。正式上线通常要另购域名，再绑定到站点。</p><h2 id="国内与境外怎么买" tabindex="-1">国内与境外怎么买 <a class="header-anchor" href="#国内与境外怎么买" aria-label="Permalink to &quot;国内与境外怎么买&quot;">​</a></h2><ul><li><strong>国内站点</strong>需要备案。Kooboo 不支持备案，建议到 <strong>阿里云</strong> 购买域名，配好解析后再添加到 Kooboo。</li><li><strong>境外站点</strong>不用备案，可直接在 Kooboo 购买。</li></ul><h2 id="在-kooboo-购买域名" tabindex="-1">在 Kooboo 购买域名 <a class="header-anchor" href="#在-kooboo-购买域名" aria-label="Permalink to &quot;在 Kooboo 购买域名&quot;">​</a></h2><p>入口在控制台 <strong>域名</strong> 页的 <strong>域名购买</strong>（或同页其它购买入口）。</p><ol><li>搜索目标域名；未被注册时可点 <strong>注册</strong>。</li><li>选择购买年限。联系方式可填可不填；不填则选自动。</li><li>点 <strong>确定</strong>，会进入支付页。</li></ol><p>本文止于进入支付页；实际付款请在后台自行完成。购买成功的域名会出现在域名列表，之后即可绑定网站。</p>',8)),t(a,{src:"/cms/manual/domains/list.jpg",alt:"在域名列表点域名购买进入购买流程"}),t(a,{src:"/cms/manual/domains/buy.jpg",alt:"搜索域名并勾选后缀后点搜索"}),o[1]||(o[1]=e('<h2 id="其他平台购买后接入" tabindex="-1">其他平台购买后接入 <a class="header-anchor" href="#其他平台购买后接入" aria-label="Permalink to &quot;其他平台购买后接入&quot;">​</a></h2><ol><li>登录域名服务商（如阿里云）的 DNS 管理，添加两条 <strong>CNAME</strong>： <ul><li>主机记录 <code>@</code>：解析根域名（如 <code>example.com</code>）</li><li>主机记录 <code>*</code>：解析子域名（如 <code>www.example.com</code>）</li></ul></li><li>记录值填 Kooboo 服务器域名。在控制台 <strong>域名 → 新建</strong> 弹窗里可以看到该值。</li><li>若服务商（如 GoDaddy）不支持根域名直接加 CNAME，可用其域名转发，把根域名转到例如 <code>www.example.com</code>。</li><li>回到 Kooboo：<strong>控制台 → 域名 → 新建域名</strong>，填入已配好 CNAME 的域名。之后即可绑定网站。</li></ol><h2 id="给网站绑定或更换域名" tabindex="-1">给网站绑定或更换域名 <a class="header-anchor" href="#给网站绑定或更换域名" aria-label="Permalink to &quot;给网站绑定或更换域名&quot;">​</a></h2><p>打开 <strong>站点设置 → 域名管理</strong>。</p><ul><li>去掉旧域名：勾选不需要的域名，再删除。刚配完 CNAME 时，因 DNS 缓存，需等 TTL 过后再访问。</li><li>绑定新域名：点 <strong>新建绑定</strong>，选要上线的正式域名。换到正式域名，等同于网站已上线。</li><li>之后用新域名访问；站点列表里也能看到当前域名。</li></ul>',5)),t(a,{src:"/cms/manual/domains/bind.jpg",alt:"在新建绑定中填写域名并选择站点后创建"}),o[2]||(o[2]=e('<h2 id="配置-dns-后无法访问" tabindex="-1">配置 DNS 后无法访问 <a class="header-anchor" href="#配置-dns-后无法访问" aria-label="Permalink to &quot;配置 DNS 后无法访问&quot;">​</a></h2><h3 id="_404-not-found" tabindex="-1">404（Not Found） <a class="header-anchor" href="#_404-not-found" aria-label="Permalink to &quot;404（Not Found）&quot;">​</a></h3><p>可能原因：域名未正确解析到 Kooboo 服务器。</p><p>排查：打开浏览器开发者工具（F12），看任意请求的 <strong>Remote Address</strong> 是否为 Kooboo 服务器 IP，或响应头 <strong>Server</strong> 是否为 Kooboo 版本号（看一项即可，Server 更易判断）。若都不是，按上一节把域名解析到 Kooboo 后再试。</p><h3 id="err-connection-reset" tabindex="-1">ERR_CONNECTION_RESET <a class="header-anchor" href="#err-connection-reset" aria-label="Permalink to &quot;ERR_CONNECTION_RESET&quot;">​</a></h3><p>可能原因：网络问题；若刚改过 DNS，也可能是 TTL 未过、解析尚未生效。</p><p>排查：换网络再访问；刚改 DNS 则等 TTL 过后再访问。</p><h3 id="err-too-many-redirects" tabindex="-1">ERR_TOO_MANY_REDIRECTS <a class="header-anchor" href="#err-too-many-redirects" aria-label="Permalink to &quot;ERR_TOO_MANY_REDIRECTS&quot;">​</a></h3><p>可能原因：CNAME 配置不当，形成重定向循环。</p><p>排查：检查 CNAME 是否正确指向 Kooboo 服务器。</p><h2 id="域名续费" tabindex="-1">域名续费 <a class="header-anchor" href="#域名续费" aria-label="Permalink to &quot;域名续费&quot;">​</a></h2><p>域名快到期时，在续费页选择年限并完成续费即可。</p>',12))])}const g=r(s,[["render",d]]);export{b as __pageData,g as default};
